const dictionaries: Record<Locale, Dictionary> = { en, tr, de, ar, "zh-CN": zhCN, fr, es };

export type Translate = ((key: UiTextKey) => string) & { locale?: Locale };

export function getTranslator(locale: Locale): Translate {
  return Object.assign((key: UiTextKey) => dictionaries[locale][key] ?? en[key] ?? key, { locale });
}

export function detectLocale(value: string | undefined): Locale {
  const normalized = value?.toLowerCase() ?? "";
  if (normalized.startsWith("tr")) return "tr";
  if (normalized.startsWith("de")) return "de";
  if (normalized.startsWith("ar")) return "ar";
  if (normalized.startsWith("zh")) return "zh-CN";
  if (normalized.startsWith("fr")) return "fr";
  if (normalized.startsWith("es")) return "es";
  return "en";
}
